/* Mesa oral */
const ORAL = [
  { p: 'B', t: 'Active Directory · árbol y bosque', ref: 'Curricula Microsoft', q: 'Diferencie árbol y bosque en Active Directory e indique el protocolo de las confianzas.', a: '<b>Árbol:</b> dominio raíz e hijos con espacio DNS contiguo. <b>Bosque:</b> uno o más árboles, con nombres posiblemente disjuntos, que comparten esquema, configuración y catálogo global; es el <b>límite de seguridad</b>. Las confianzas internas son automáticas, bidireccionales y transitivas, con <b>Kerberos v5</b>.' },
  { p: 'A', t: 'Redes · tramas con error', ref: 'Uyless Black', q: '¿Qué hace un switch de capa 2 al recibir una trama con errores?', a: 'En store-and-forward recibe la trama completa y calcula el <b>FCS (CRC-32)</b>. Si no coincide, <b>la descarta en silencio</b>: Ethernet no es confiable. La detección de pérdida y la retransmisión corresponden a <b>TCP</b> en la capa 4.' },
  { p: 'D', t: 'Bases de datos · índices', ref: 'Prescott', q: 'Explique la diferencia entre índice clustered y nonclustered.', a: 'El <b>clustered</b> define el orden físico de las filas: las hojas del árbol B son los datos, y por eso hay <b>uno por tabla</b> (por defecto con la PK). El <b>nonclustered</b> es una estructura aparte cuyas hojas tienen localizadores (RID o clave clustered); puede haber hasta 999. Aceleran lecturas y penalizan escrituras.' },
  { p: 'D', t: 'Normalización · 4FN y 5FN', ref: 'Nevado Cabello', q: 'Justifique la necesidad de 4FN y 5FN en un sistema logístico.', a: 'La <b>4FN</b> elimina dependencias multivaluadas independientes: un oficial con N cursos y N idiomas genera combinaciones redundantes; se separa en dos tablas binarias. La <b>5FN</b> elimina dependencias de unión cíclicas ternarias (Oficial, Vehículo, Zona) que solo se descomponen en <b>tres proyecciones</b> sin tuplas espurias (trabajos de Fagin).' },
  { p: 'B', t: 'Windows · impresoras', ref: 'Curricula Microsoft', q: 'Describa la administración de impresoras: permisos, pool y prioridades.', a: 'Se distingue <b>impresora</b> (lógica) de <b>dispositivo</b> (físico). Se instala el rol de servicios de impresión, se crea el puerto TCP/IP, se cargan drivers x86/x64, se comparte y se publica en AD o se despliega por GPO. Permisos: <b>Imprimir</b>, <b>Administrar documentos</b> y <b>Administrar esta impresora</b>. <b>Pool:</b> una lógica con varios dispositivos idénticos. <b>Prioridades:</b> varias lógicas sobre un dispositivo, de 1 a 99.' },
  { p: 'B', t: 'Windows · DHCP y DNS', ref: 'TechNet', q: 'Explique el proceso DORA y la integración DHCP-DNS.', a: '<b>Discover</b> (broadcast del cliente), <b>Offer</b>, <b>Request</b> y <b>Acknowledge</b>, por UDP 67/68. Entre subredes se usa un agente de retransmisión. Con integración dinámica, el servidor DHCP registra los registros <b>A</b> y <b>PTR</b> del cliente, con actualización segura en zonas integradas en AD. En un dominio, el DHCP debe estar <b>autorizado</b>.' },
  { p: 'A', t: 'Redes · fibra óptica', ref: 'Castro Lechtaler', q: 'Diferencie fibra monomodo y multimodo y sus ámbitos de empleo.', a: '<b>Monomodo:</b> núcleo ~9 µm, láser, mínima dispersión, decenas de km (WAN, troncales). <b>Multimodo:</b> núcleo 50/62,5 µm, LED o VCSEL, mayor dispersión modal, cientos de metros (edificios, campus). Ambas son inmunes a la interferencia electromagnética y no irradian señal: ventaja de seguridad.' },
  { p: 'C', t: 'Desarrollo · traductores', ref: 'Teoría de traductores', q: 'Diferencie compilador, intérprete y compaginador.', a: 'El <b>compilador</b> traduce todo el fuente antes de ejecutar (léxico, sintáctico, semántico, intermedio, optimización, objeto). El <b>intérprete</b> traduce y ejecuta instrucción por instrucción. El <b>compaginador (linker)</b> no traduce: une módulos objeto y bibliotecas (estáticas o DLL) resolviendo referencias y genera el ejecutable.' },
  { p: 'C', t: 'Desarrollo · programación estructurada', ref: 'Böhm-Jacopini · Dijkstra', q: 'Fundamente la programación estructurada y su teorema de base.', a: 'El teorema de <b>Böhm-Jacopini</b> (1966) demuestra que todo algoritmo puede escribirse con <b>secuencia, selección e iteración</b>. <b>Dijkstra</b> (1968) propuso abandonar el GOTO. Principios: diseño descendente, una entrada y una salida, módulos con alta cohesión y bajo acoplamiento.' },
  { p: 'D', t: 'Bases de datos · E-R', ref: 'Nevado Cabello', q: 'Defina grado y cardinalidad de una relación E-R y cómo se reduce una N:M.', a: '<b>Grado:</b> cantidad de entidades que participan (unaria, binaria, ternaria). <b>Cardinalidad:</b> cuántas instancias se asocian (1:1, 1:N, N:M) y su participación mínima/máxima. La <b>N:M</b> genera una tabla intermedia con las claves de ambas entidades como clave compuesta; la 1:N se resuelve con FK en el lado N.' },
  { p: 'B', t: 'Windows · VPN', ref: 'TechNet', q: 'Compare PPTP y L2TP/IPSec para acceso remoto institucional.', a: '<b>PPTP:</b> TCP 1723 + GRE, cifrado MPPE con MS-CHAPv2: obsoleto e inseguro. <b>L2TP/IPSec:</b> túnel L2TP (UDP 1701) protegido por <b>IPSec ESP</b> (AES + integridad), con certificados o clave precompartida y claves por IKE. Recomendación: L2TP/IPSec, SSTP o IKEv2, con autenticación centralizada por <b>RADIUS/NPS</b>.' },
  { p: 'D', t: 'Bases de datos · DELETE vs TRUNCATE', ref: 'T-SQL', q: 'Diferencie DELETE y TRUNCATE en SQL Server.', a: '<b>DELETE:</b> fila por fila, registra cada una en el log, admite WHERE y dispara triggers. <b>TRUNCATE:</b> desasigna páginas con registro mínimo, no admite WHERE ni dispara triggers, reinicia IDENTITY y no procede si una FK referencia la tabla.' },
  { p: 'C', t: 'Algoritmia · diagrama y pseudocódigo', ref: 'Modelo de Examen', q: '¿Qué diferencia hay entre un diagrama de flujo y el pseudocódigo, y qué es una prueba de escritorio?', a: 'Ambos representan un algoritmo: el <b>diagrama de flujo</b> lo hace gráficamente con símbolos normalizados (terminal, proceso, entrada/salida, decisión, conector) y el <b>pseudocódigo</b> con lenguaje estructurado cercano al natural (Si, Mientras, Para). La <b>prueba de escritorio</b> es ejecutar el algoritmo a mano registrando en una tabla el valor de cada variable paso a paso, para verificarlo o deducir su salida.' },
  { p: 'C', t: 'Algoritmia · estructuras de repetición', ref: 'PSeInt', q: 'Compare Mientras, Repetir y Para.', a: '<b>Mientras</b> evalúa la condición antes: puede no ejecutarse nunca. <b>Repetir … Hasta Que</b> evalúa al final: se ejecuta al menos una vez y termina cuando la condición es verdadera. <b>Para</b> se usa cuando la cantidad de vueltas se conoce de antemano y maneja la variable de control automáticamente.' },
  { p: 'C', t: 'POO · pilares', ref: 'Modelo de Examen', q: 'Explique los pilares de la programación orientada a objetos con un ejemplo.', a: '<b>Abstracción:</b> modelar solo lo esencial (Vehículo con patente y velocidad). <b>Encapsulamiento:</b> atributos privados accesibles por métodos. <b>Herencia:</b> Camión y Blindado extienden Vehículo. <b>Polimorfismo:</b> mover() se comporta distinto en cada subclase. Lenguajes: Java, C#, C++, Python.' },
  { p: 'C', t: 'UML', ref: 'OMG UML', q: '¿Qué es UML y qué diagramas usaría para documentar un sistema de control de material?', a: 'UML es un <b>lenguaje gráfico estándar (OMG)</b> para especificar y documentar sistemas; no es una metodología. Usaría <b>casos de uso</b> para los requerimientos (actores: encargado, auditor), <b>clases</b> para la estructura (Material, Depósito, Movimiento, con asociaciones y multiplicidades), <b>secuencia</b> para el flujo de un retiro, y <b>despliegue</b> para la infraestructura.' },
  { p: 'C', t: 'Web · evolución', ref: 'Carballar · MDN', q: 'Explique el nacimiento de la web y las nuevas tendencias.', a: 'Berners-Lee crea en el <b>CERN</b> (1989-91) HTML, HTTP y la URL; Mosaic (1993) la populariza y en 1994 nace el W3C. JavaScript (1995) y el DOM habilitan el <b>DHTML</b>; AJAX (2005) las aplicaciones dinámicas. Tendencias: <b>SPA</b>, <b>PWA</b>, SSR, APIs REST/GraphQL, microservicios y serverless, WebAssembly y seguridad por defecto (HTTPS).' },
  { p: 'C', t: 'Web · PHP y ASP', ref: 'Eslava Muñoz · IIS', q: 'Compare PHP y ASP clásico.', a: '<b>PHP:</b> código abierto, corre en Apache/Nginx (pilas LAMP/WAMP), sintaxis <code class="inl">&lt;?php ?&gt;</code>, variables $, sesiones con session_start() y $_SESSION, acceso a MySQL con mysqli/PDO. <b>ASP clásico:</b> Microsoft, corre en IIS, VBScript, objetos Request, Response, Server, Session y Application, global.asa y ADO. Ambos ejecutan en el servidor y envían HTML.' },
  { p: 'A', t: 'Redes · subneteo', ref: 'CCNA', q: 'Explique cómo obtiene la red, el broadcast y los hosts de 172.16.89.45/22.', a: 'El corte cae en el <b>tercer octeto</b> (16 + 6 bits): máscara 255.255.252.0. <b>Salto</b> = 256 − 252 = 4. El múltiplo de 4 inferior a 89 es 88: red <b>172.16.88.0</b>. Siguiente red 172.16.92.0 → broadcast <b>172.16.91.255</b>. Hosts útiles 2<sup>10</sup> − 2 = <b>1022</b> (172.16.88.1 a 172.16.91.254).' },
  { p: 'A', t: 'Redes · RIP vs OSPF', ref: 'CCNA', q: 'Compare RIP y OSPF y explique la distancia administrativa.', a: '<b>RIP:</b> vector distancia, métrica saltos (máx. 15), actualizaciones periódicas, convergencia lenta, split horizon. <b>OSPF:</b> estado de enlace, Dijkstra/SPF, métrica costo por ancho de banda, áreas con área 0, convergencia rápida. La <b>distancia administrativa</b> elige entre fuentes distintas: conectada 0, estática 1, EIGRP 90, OSPF 110, RIP 120.' },
  { p: 'B', t: 'Windows · sitios', ref: 'Curricula Microsoft', q: '¿Qué es un sitio de Active Directory y cómo replica?', a: 'Un <b>sitio</b> agrupa subredes bien conectadas. <b>Intrasitio:</b> por notificación (~15 s), sin comprimir, en anillo generado por el KCC. <b>Intersitio:</b> programada (180 min por defecto) y comprimida, entre cabezas de puente, por vínculos con costo. Transportes: RPC sobre IP (todo) y SMTP (sin partición de dominio).' },
  { p: 'D', t: 'Modelo relacional · claves', ref: 'Nevado Cabello', q: 'Defina superclave, clave candidata, primaria y foránea.', a: '<b>Superclave:</b> atributos que identifican cada fila. <b>Candidata:</b> superclave mínima. <b>Primaria:</b> la candidata elegida (no nula, única). <b>Alternativas:</b> las candidatas no elegidas. <b>Foránea:</b> atributo que referencia la PK de otra tabla e implementa la integridad referencial.' },
];

